import { StyleSheet } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

/**
 * Creates all progress styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createProgressStyles = (t: PdfcnTheme) => {
  const { borderRadius, spacing, fontWeights, typography } = t.primitives;

  return StyleSheet.create({
    container: {
      display: "flex",
      flexDirection: "column",
      gap: spacing[3],
      marginBottom: t.spacing.componentGap,
      width: "100%",
    },
    fill: {
      borderRadius: borderRadius.full,
      height: spacing[2],
    },
    item: {
      display: "flex",
      flexDirection: "column",
      gap: spacing[1],
    },
    label: {
      color: t.colors.foreground,
      flex: 1,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.sm,
      fontWeight: fontWeights.medium,
    },
    labelRow: {
      alignItems: "center",
      display: "flex",
      flexDirection: "row",
    },
    track: {
      backgroundColor: t.colors.muted,
      borderRadius: borderRadius.full,
      height: spacing[2],
      width: "100%",
    },
    value: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.sm,
      marginLeft: spacing[3],
    },
  });
};

import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/components/pdf/theme-provider";
import {
  View,
  Text as PDFText,
} from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import { resolveColor } from "@/lib/resolve-color";

import { createProgressStyles } from "./progress.styles";
import type { PdfProgressProps } from "./progress.types";

/** Clamps a percentage to 0-100; non-finite values render as an empty bar. */
const clampPercent = (value: number): number =>
  Number.isFinite(value) ? Math.min(100, Math.max(0, value)) : 0;

export const PdfProgress = ({
  items,
  showValues = true,
  accentColor = "primary",
  style,
  noWrap = false,
}: PdfProgressProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createProgressStyles(theme), [theme]);
  const fillColor = resolveColor(accentColor, theme.colors);

  const containerStyles: Style[] = style
    ? [styles.container, style]
    : [styles.container];

  return (
    <View wrap={!noWrap} style={containerStyles}>
      {items.map((item, index) => {
        const percent = clampPercent(item.value);
        const valueLabel = `${Math.round(percent)}%`;
        return (
          // Keep each label with its bar when the list breaks across pages.
          <View key={`${item.label}-${index}`} wrap={false} style={styles.item}>
            <View style={styles.labelRow}>
              <PDFText style={styles.label}>{item.label}</PDFText>
              {showValues ? (
                <PDFText style={styles.value}>{valueLabel}</PDFText>
              ) : null}
            </View>
            <View style={styles.track}>
              {/* A zero-width fill still draws a hairline, so skip it at 0%. */}
              {percent > 0 ? (
                <View
                  style={[
                    styles.fill,
                    { backgroundColor: fillColor, width: `${percent}%` },
                  ]}
                />
              ) : null}
            </View>
          </View>
        );
      })}
    </View>
  );
};

import type { Style } from "@/lib/pdf-primitives";

/**
 * A single labeled progress bar.
 * Props - `label` | `value`
 * @see {@link ProgressItem}
 */
export interface ProgressItem {
  label: string;
  /** Percentage from 0 to 100. Values outside that range are clamped. */
  value: number;
}

/**
 * Labeled percentage bars for skills, goals, and initiative tracking.
 * Props - `items` | `showValues` | `accentColor` | `style` | `noWrap`
 * @see {@link PdfProgressProps}
 */
export interface PdfProgressProps {
  items: ProgressItem[];
  /**
   * @default true
   */
  showValues?: boolean;
  /**
   * Theme color key (e.g. `'success'`) or any CSS color.
   * @default 'primary'
   */
  accentColor?: string;
  style?: Style;
  /**
   * @default false
   */
  noWrap?: boolean;
}
